#include <Native/Artwork.h>
#include <Native/CanvasView.h>
#include <Native/ToolSettings.h>
#include <iiFileProviderNative.h>
#include <iiSharedCanvasNative.h>
#include <filesystem>
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace congregation::native;using namespace iiSharedCanvas;
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
const RasterLayer& pixels(const Artwork& art){for(const auto& l:art.document().layers)if(layerProperties(l).id==art.selected()){const auto* source=staticLayerSource(l);check(source!=nullptr,"source missing");const auto* asset=findRasterAsset(art.document(),source->assetId);check(asset!=nullptr,"asset missing");return asset->pixels;}throw std::runtime_error("layer missing");}
void input(CanvasView& view,ii::gui::WidgetInputKind kind,double timestamp){ii::gui::WidgetInput e;e.kind=kind;e.x=16;e.y=16;e.buttons=1;e.timestamp=timestamp;check(view.input(e).has_value(),"input failed");}
int main() try {
 iiFileProvider::native::TemporaryDirectory dir(std::filesystem::temp_directory_path());check(dir.isValid(),"temp unavailable");ToolSettings settings;settings.set(ToolParameter::size,12);settings.set(ToolParameter::flow,20);settings.set(ToolParameter::opacity,100);settings.set(ToolParameter::taper,0);settings.set(ToolParameter::stabilization,0);settings.set(ToolParameter::post,0);auto brush=settings.brush("airbrush");brush.argb=0xff000000U;
 Artwork art(dir.path());check(art.create(32,32),"create failed");CanvasView view(art);view.tool="brush";view.settings=brush;view.brush_size=12;view.opacity=1;view.color=0xff000000U;using K=ii::gui::WidgetInputKind;
 check(!view.airbrush_active()&&!view.airbrush_tick(.1),"idle tick admitted");input(view,K::pointer_down,100);check(view.airbrush_active(),"airbrush was not started");const auto rev=art.revision();const auto first=pixels(art).pixels[16*32+16]>>24;check(!view.airbrush_tick(std::numeric_limits<double>::quiet_NaN()),"invalid tick admitted");check(view.airbrush_tick(.2),"stationary tick failed");const auto second=pixels(art).pixels[16*32+16]>>24;check(second>first&&art.revision()==rev,"stationary spray preview did not grow");input(view,K::pointer_up,100.2);check(!view.airbrush_active(),"airbrush did not stop");auto result=pixels(art).pixels;check(art.undo()&&art.redo()&&pixels(art).pixels==result,"airbrush history failed");
 Artwork reference(dir.path());check(reference.create(32,32),"reference create failed");CanvasView ref(reference);ref.tool="brush";ref.settings=brush;ref.brush_size=12;ref.opacity=1;ref.color=0xff000000U;input(ref,K::pointer_down,100);input(ref,K::pointer_up,100.2);check(pixels(reference).pixels==result,"timer and input clocks double-counted time");
 check(art.undo()&&art.can_redo(),"cancel setup failed");const auto undoRevision=art.revision();input(view,K::pointer_down,101);check(view.airbrush_tick(.1),"cancel tick failed");ii::gui::WidgetInput escape;escape.kind=K::key_down;escape.key=ii::gui::WidgetKey::escape;check(view.input(escape).has_value(),"cancel input failed");check(!view.airbrush_active()&&!view.airbrush_tick(.3)&&art.can_redo()&&art.revision()==undoRevision,"cancel changed document or redo");
 input(view,K::pointer_down,102);check(view.airbrush_tick(.1),"tool change tick failed");view.tool="crop";check(!view.airbrush_active()&&!view.airbrush_tick(.2),"tool change left airbrush timer active");view.cancel_airbrush_stroke();check(art.can_redo()&&art.revision()==undoRevision,"tool change cancel changed history");view.tool="brush";
 Artwork selected(dir.path());check(selected.create(32,32)&&selected.set_selection(SelectionGeometry::Rectangle,{16,0},{32,32}),"selected fixture failed");CanvasView sv(selected);sv.tool="brush";sv.settings=brush;sv.brush_size=12;sv.opacity=1;sv.color=0xff000000U;input(sv,K::pointer_down,200);check(sv.airbrush_tick(.2),"selected tick failed");input(sv,K::pointer_up,200.2);auto selectedPixels=pixels(selected).pixels;bool painted=false;for(int y=0;y<32;++y)for(int x=0;x<32;++x){auto alpha=selectedPixels[std::size_t(y)*32+x]>>24;if(x<16)check(alpha==0,"airbrush escaped selection");else painted|=alpha!=0;}check(painted&&selected.undo()&&selected.redo()&&pixels(selected).pixels==selectedPixels,"selected airbrush history failed");
 Artwork masked(dir.path());check(masked.create(32,32),"quick mask fixture failed");CanvasView qv(masked);qv.tool="brush";qv.settings=brush;qv.brush_size=12;qv.opacity=1;check(qv.begin_quick_mask(),"quick mask start failed");const auto maskRevision=masked.revision();input(qv,K::pointer_down,300);check(qv.airbrush_active()&&qv.airbrush_tick(.2),"quick mask tick failed");input(qv,K::pointer_up,300.2);check(qv.commit_quick_mask()&&masked.selection_mask()&&masked.selection_mask()->alpha[16*32+16]<255&&masked.revision()==maskRevision,"quick mask airbrush failed");const auto completedMask=masked.selection_mask()->alpha;check(qv.begin_quick_mask(),"second quick mask start failed");input(qv,K::pointer_down,301);check(qv.airbrush_tick(.1),"second quick mask tick failed");qv.cancel_airbrush_stroke();check(qv.quick_mask_active()&&!qv.airbrush_active(),"quick mask session lost on tool change");check(qv.commit_quick_mask()&&masked.selection_mask()->alpha==completedMask,"quick mask cancellation changed earlier work");check(masked.undo()&&!masked.selection_mask()&&masked.redo()&&masked.selection_mask(),"quick mask airbrush history failed");
 std::cout<<"AIRBRUSH_TIMER_INTEGRATION_OK\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
